-- ==============================================================
--  HOTEL INDUSTRY CAPSTONE — FULL DATABASE SETUP + QUERIES
--  Analyst  : Pratik Chorghe
--  Database : MySQL 8.0+
--  Run this entire file once → all tables created + loaded
-- ==============================================================

DROP DATABASE IF EXISTS hotel_db;
CREATE DATABASE hotel_db
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;
USE hotel_db;

-- ==============================================================
-- TABLE 1: dim_chain
-- ==============================================================
CREATE TABLE dim_chain (
    Chain_ID            VARCHAR(10)  PRIMARY KEY,
    Chain_Name          VARCHAR(100) NOT NULL,
    HQ_Location         VARCHAR(100),
    Founded_Year        INT,
    Global_Properties   INT,
    Stock_Ticker        VARCHAR(10),
    Segment             VARCHAR(50),
    Sub_Brand_Count     INT
);


-- ==============================================================
-- TABLE 2: dim_location
-- ==============================================================
CREATE TABLE dim_location (
    City                    VARCHAR(100) NOT NULL,
    Country                 VARCHAR(100) NOT NULL,
    Region                  VARCHAR(100),
    Sub_Region              VARCHAR(100),
    Latitude                DECIMAL(8,4),
    Longitude               DECIMAL(8,4),
    Currency                VARCHAR(10),
    Price_Tier_Multiplier   DECIMAL(4,2),
    PRIMARY KEY (City, Country)
);


-- ==============================================================
-- TABLE 3: dim_hotel
-- ==============================================================
CREATE TABLE dim_hotel (
    Hotel_ID        INT          PRIMARY KEY,
    Hotel_Name      VARCHAR(200) NOT NULL,
    Chain           VARCHAR(100),
    Sub_Chain       VARCHAR(100),
    Star_Rating     TINYINT,
    Segment         VARCHAR(50),
    City            VARCHAR(100),
    Country         VARCHAR(100),
    Latitude        DECIMAL(8,4),
    Longitude       DECIMAL(8,4),
    Total_Rooms     INT,
    Year_Opened     INT,
    Chain_ID        VARCHAR(10),
    FOREIGN KEY (Chain_ID) REFERENCES dim_chain(Chain_ID)
);











-- ==============================================================
-- TABLE 4: fact_revenue  (5,500 rows)
-- ==============================================================
CREATE TABLE fact_revenue (
    Transaction_ID  VARCHAR(20)     PRIMARY KEY,
    Hotel_ID        INT,
    Chain_ID        VARCHAR(10),
    City            VARCHAR(100),
    Country         VARCHAR(100),
    Region          VARCHAR(100),
    Year            SMALLINT,
    Quarter         VARCHAR(5),
    Revenue_USD     BIGINT,
    ADR_USD         INT,
    RevPAR_USD      DECIMAL(10,2),
    TRevPAR_USD     DECIMAL(10,2),
    Occupancy_Pct   DECIMAL(5,1),
    GOP_Pct         DECIMAL(5,1),
    Rooms_Available INT,
    Google_Rating   DECIMAL(3,1),
    Reviews_Count   INT,
    Revenue_Type    VARCHAR(20),
    Segment         VARCHAR(50),
    Star_Rating     TINYINT,
    Currency        VARCHAR(10),
    Latitude        DECIMAL(8,4),
    Longitude       DECIMAL(8,4),
    FOREIGN KEY (Hotel_ID)  REFERENCES dim_hotel(Hotel_ID),
    FOREIGN KEY (Chain_ID)  REFERENCES dim_chain(Chain_ID)
);












-- ==============================================================
-- VERIFY ALL TABLES LOADED CORRECTLY
-- Run this after the file finishes to confirm row counts
-- ==============================================================
SELECT 'dim_chain'    AS Table_Name, COUNT(*) AS Row_Count FROM dim_chain
UNION ALL
SELECT 'dim_location',                COUNT(*)             FROM dim_location
UNION ALL
SELECT 'dim_hotel',                   COUNT(*)             FROM dim_hotel
UNION ALL
SELECT 'fact_revenue',                COUNT(*)             FROM fact_revenue;

-- Expected:
-- dim_chain     →  12 rows
-- dim_location  → 250 rows
-- dim_hotel     → 4,640 rows
-- fact_revenue  → 5,500 rows


-- ==============================================================
-- ██████████████  SQL ANALYSIS QUERIES  ████████████████████████
-- ==============================================================


-- ==============================================================
-- QUERY 1 — Revenue, RevPAR, ADR, Occupancy by Year
-- Business Q: How did hotel performance trend 2019-2025?
-- ==============================================================
SELECT
    Year,
    Revenue_Type                              AS Data_Type,
    COUNT(*)                                  AS Transactions,
    ROUND(SUM(Revenue_USD) / 1e6, 2)         AS Total_Revenue_M,
    ROUND(AVG(RevPAR_USD),  2)               AS Avg_RevPAR,
    ROUND(AVG(ADR_USD),     2)               AS Avg_ADR,
    ROUND(AVG(Occupancy_Pct), 2)             AS Avg_Occupancy_Pct,
    ROUND(AVG(GOP_Pct), 2)                   AS Avg_GOP_Pct
FROM fact_revenue
GROUP BY Year, Revenue_Type
ORDER BY Year;


-- ==============================================================
-- QUERY 2 — Chains with Avg RevPAR > $200 (GROUP BY + HAVING)
-- Business Q: Which chains deliver premium RevPAR?
-- ==============================================================
SELECT
    Chain_ID,
    COUNT(*)                                  AS Total_Records,
    ROUND(SUM(Revenue_USD) / 1e6, 2)         AS Total_Revenue_M,
    ROUND(AVG(RevPAR_USD),  2)               AS Avg_RevPAR,
    ROUND(AVG(ADR_USD),     2)               AS Avg_ADR,
    ROUND(AVG(Occupancy_Pct), 2)             AS Avg_Occupancy_Pct,
    ROUND(AVG(GOP_Pct), 2)                   AS Avg_GOP_Pct
FROM fact_revenue
GROUP BY Chain_ID
HAVING AVG(RevPAR_USD) > 200
ORDER BY Avg_RevPAR DESC;


-- ==============================================================
-- QUERY 3 — RANK countries by revenue within each Region
-- Business Q: Which countries lead inside their region?
-- ==============================================================
SELECT
    Region,
    Country,
    ROUND(SUM(Revenue_USD) / 1e6, 2)         AS Total_Revenue_M,
    ROUND(AVG(RevPAR_USD), 2)                AS Avg_RevPAR,
    RANK() OVER (
        PARTITION BY Region
        ORDER BY SUM(Revenue_USD) DESC
    )                                          AS Revenue_Rank_In_Region
FROM fact_revenue
GROUP BY Region, Country
ORDER BY Region, Revenue_Rank_In_Region;


-- ==============================================================
-- QUERY 4 — LAG: Year-over-Year Revenue Growth by Chain
-- Business Q: Which chains recovered fastest after COVID?
-- ==============================================================
WITH yearly_chain AS (
    SELECT
        Chain_ID,
        Year,
        ROUND(SUM(Revenue_USD) / 1e6, 2)     AS Revenue_M
    FROM fact_revenue
    WHERE Revenue_Type = 'Reported'
    GROUP BY Chain_ID, Year
)
SELECT
    Chain_ID,
    Year,
    Revenue_M,
    LAG(Revenue_M) OVER (
        PARTITION BY Chain_ID ORDER BY Year
    )                                          AS Prev_Year_Revenue_M,
    ROUND(
        (Revenue_M - LAG(Revenue_M) OVER (PARTITION BY Chain_ID ORDER BY Year))
        / NULLIF(LAG(Revenue_M) OVER (PARTITION BY Chain_ID ORDER BY Year), 0)
        * 100, 2
    )                                          AS YoY_Growth_Pct
FROM yearly_chain
ORDER BY Chain_ID, Year;


-- ==============================================================
-- QUERY 5 — CTE: Cumulative Revenue by Quarter
-- Business Q: How did global revenue build quarter by quarter?
-- ==============================================================
WITH quarterly AS (
    SELECT
        Year,
        Quarter,
        ROUND(SUM(Revenue_USD) / 1e6, 2)     AS Revenue_M
    FROM fact_revenue
    GROUP BY Year, Quarter
)
SELECT
    Year,
    Quarter,
    Revenue_M,
    ROUND(SUM(Revenue_M) OVER (
        ORDER BY Year, Quarter
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ), 2)                                      AS Cumulative_Revenue_M
FROM quarterly
ORDER BY Year, Quarter;


-- ==============================================================
-- QUERY 6 — Subquery: Hotels above their Country Avg RevPAR
-- Business Q: Which hotels are outperforming their market?
-- ==============================================================
SELECT
    f.Hotel_ID,
    h.Hotel_Name,
    h.Sub_Chain,
    f.City,
    f.Country,
    ROUND(AVG(f.RevPAR_USD), 2)              AS Hotel_Avg_RevPAR,
    ROUND(ca.Country_Avg_RevPAR, 2)          AS Country_Avg_RevPAR,
    ROUND(AVG(f.RevPAR_USD) - ca.Country_Avg_RevPAR, 2)
                                               AS RevPAR_Above_Avg
FROM fact_revenue f
JOIN dim_hotel h ON f.Hotel_ID = h.Hotel_ID
JOIN (
    SELECT Country, AVG(RevPAR_USD) AS Country_Avg_RevPAR
    FROM fact_revenue
    GROUP BY Country
) ca ON f.Country = ca.Country
GROUP BY f.Hotel_ID, h.Hotel_Name, h.Sub_Chain, f.City, f.Country, ca.Country_Avg_RevPAR
HAVING AVG(f.RevPAR_USD) > ca.Country_Avg_RevPAR
ORDER BY RevPAR_Above_Avg DESC
LIMIT 25;


-- ==============================================================
-- QUERY 7 — DENSE_RANK: Top 3 Cities per Country by Occupancy
-- Business Q: Which cities are most in-demand per country?
-- ==============================================================
WITH city_occ AS (
    SELECT
        Country,
        City,
        ROUND(AVG(Occupancy_Pct), 2)         AS Avg_Occupancy_Pct,
        ROUND(AVG(RevPAR_USD), 2)            AS Avg_RevPAR,
        DENSE_RANK() OVER (
            PARTITION BY Country
            ORDER BY AVG(Occupancy_Pct) DESC
        )                                      AS Occ_Rank
    FROM fact_revenue
    GROUP BY Country, City
)
SELECT *
FROM city_occ
WHERE Occ_Rank <= 3
ORDER BY Country, Occ_Rank;


-- ==============================================================
-- QUERY 8 — CTE + CASE: Hotel Performance Classification
-- Business Q: Classify hotels as Top/Good/Average/Below
-- ==============================================================
WITH hotel_perf AS (
    SELECT
        f.Hotel_ID,
        h.Hotel_Name,
        h.Sub_Chain,
        f.Country,
        h.Star_Rating,
        ROUND(AVG(f.RevPAR_USD), 2)          AS Avg_RevPAR,
        ROUND(AVG(f.Occupancy_Pct), 2)       AS Avg_Occupancy,
        ROUND(SUM(f.Revenue_USD) / 1e6, 2)   AS Total_Revenue_M,
        ROUND(AVG(f.GOP_Pct), 2)             AS Avg_GOP_Pct
    FROM fact_revenue f
    JOIN dim_hotel h ON f.Hotel_ID = h.Hotel_ID
    WHERE f.Revenue_Type = 'Reported'
    GROUP BY f.Hotel_ID, h.Hotel_Name, h.Sub_Chain, f.Country, h.Star_Rating
)
SELECT
    Hotel_Name, Sub_Chain, Country, Star_Rating,
    Avg_RevPAR, Avg_Occupancy, Total_Revenue_M, Avg_GOP_Pct,
    CASE
        WHEN Avg_RevPAR >= 300 AND Avg_Occupancy >= 70 THEN 'Top Performer'
        WHEN Avg_RevPAR >= 150 AND Avg_Occupancy >= 60 THEN 'Good Performer'
        WHEN Avg_RevPAR >= 80  AND Avg_Occupancy >= 50 THEN 'Average Performer'
        ELSE 'Below Average'
    END                                        AS Performance_Category
FROM hotel_perf
ORDER BY Avg_RevPAR DESC
LIMIT 50;


-- ==============================================================
-- QUERY 9 — NTILE: Segment Hotels into Revenue Quartiles
-- Business Q: What does the revenue distribution look like?
-- ==============================================================
WITH hotel_rev AS (
    SELECT
        f.Hotel_ID,
        h.Hotel_Name,
        f.Country,
        h.Sub_Chain,
        h.Star_Rating,
        ROUND(SUM(f.Revenue_USD) / 1e6, 2)   AS Total_Revenue_M
    FROM fact_revenue f
    JOIN dim_hotel h ON f.Hotel_ID = h.Hotel_ID
    WHERE f.Revenue_Type = 'Reported'
    GROUP BY f.Hotel_ID, h.Hotel_Name, f.Country, h.Sub_Chain, h.Star_Rating
)
SELECT
    Hotel_Name, Sub_Chain, Country, Star_Rating, Total_Revenue_M,
    NTILE(4) OVER (ORDER BY Total_Revenue_M)  AS Revenue_Quartile,
    CASE NTILE(4) OVER (ORDER BY Total_Revenue_M)
        WHEN 1 THEN 'Bottom 25%'
        WHEN 2 THEN 'Lower-Mid 25%'
        WHEN 3 THEN 'Upper-Mid 25%'
        WHEN 4 THEN 'Top 25%'
    END                                        AS Quartile_Label
FROM hotel_rev
ORDER BY Total_Revenue_M DESC
LIMIT 50;


-- ==============================================================
-- QUERY 10 — Multi-CTE: COVID Impact & Recovery by Chain
-- Business Q: Which chains dropped most? Recovered fastest?
-- ==============================================================
WITH pre_covid AS (
    SELECT Chain_ID, ROUND(AVG(Revenue_USD)/1e3, 2) AS Rev_2019_K
    FROM fact_revenue WHERE Year = 2019 GROUP BY Chain_ID
),
covid_yr AS (
    SELECT Chain_ID, ROUND(AVG(Revenue_USD)/1e3, 2) AS Rev_2020_K
    FROM fact_revenue WHERE Year = 2020 GROUP BY Chain_ID
),
recovery AS (
    SELECT Chain_ID, ROUND(AVG(Revenue_USD)/1e3, 2) AS Rev_2023_K
    FROM fact_revenue WHERE Year = 2023 GROUP BY Chain_ID
),
peak_yr AS (
    SELECT Chain_ID, ROUND(AVG(Revenue_USD)/1e3, 2) AS Rev_2024_K
    FROM fact_revenue WHERE Year = 2024 GROUP BY Chain_ID
)
SELECT
    p.Chain_ID,
    p.Rev_2019_K     AS Pre_COVID_2019_K,
    c.Rev_2020_K     AS COVID_2020_K,
    ROUND((c.Rev_2020_K - p.Rev_2019_K) / NULLIF(p.Rev_2019_K,0) * 100, 1)
                      AS Drop_Pct_2020,
    r.Rev_2023_K     AS Recovery_2023_K,
    pk.Rev_2024_K    AS Peak_2024_K,
    ROUND((pk.Rev_2024_K - p.Rev_2019_K) / NULLIF(p.Rev_2019_K,0) * 100, 1)
                      AS Growth_vs_PreCOVID_Pct,
    CASE
        WHEN pk.Rev_2024_K >= p.Rev_2019_K        THEN 'Fully Recovered'
        WHEN pk.Rev_2024_K >= p.Rev_2019_K * 0.85 THEN 'Almost Recovered'
        ELSE 'Still Recovering'
    END               AS Recovery_Status
FROM pre_covid p
JOIN covid_yr c  ON p.Chain_ID = c.Chain_ID
JOIN recovery r  ON p.Chain_ID = r.Chain_ID
JOIN peak_yr pk  ON p.Chain_ID = pk.Chain_ID
ORDER BY Growth_vs_PreCOVID_Pct DESC;


-- ==============================================================
-- QUERY 11 — FIRST_VALUE: Best & Worst Quarter per Country
-- Business Q: When is peak season for each country?
-- ==============================================================
WITH country_quarter AS (
    SELECT
        Country, Quarter,
        ROUND(AVG(RevPAR_USD), 2)            AS Avg_RevPAR,
        ROUND(AVG(Occupancy_Pct), 2)         AS Avg_Occupancy
    FROM fact_revenue
    GROUP BY Country, Quarter
)
SELECT DISTINCT
    Country,
    FIRST_VALUE(Quarter)   OVER (PARTITION BY Country ORDER BY Avg_RevPAR DESC) AS Best_Quarter,
    FIRST_VALUE(Avg_RevPAR) OVER (PARTITION BY Country ORDER BY Avg_RevPAR DESC) AS Best_RevPAR,
    FIRST_VALUE(Quarter)   OVER (PARTITION BY Country ORDER BY Avg_RevPAR ASC)  AS Worst_Quarter,
    FIRST_VALUE(Avg_RevPAR) OVER (PARTITION BY Country ORDER BY Avg_RevPAR ASC) AS Worst_RevPAR
FROM country_quarter
ORDER BY Country;


-- ==============================================================
-- QUERY 12 — Segment Profitability: Luxury vs Economy
-- Business Q: Is luxury always more profitable?
-- ==============================================================
SELECT
    Segment,
    COUNT(DISTINCT Hotel_ID)                  AS Unique_Hotels,
    COUNT(*)                                  AS Total_Transactions,
    ROUND(SUM(Revenue_USD) / 1e9, 3)         AS Total_Revenue_B,
    ROUND(AVG(RevPAR_USD), 2)                AS Avg_RevPAR,
    ROUND(AVG(ADR_USD), 2)                   AS Avg_ADR,
    ROUND(AVG(Occupancy_Pct), 2)             AS Avg_Occupancy_Pct,
    ROUND(AVG(GOP_Pct), 2)                   AS Avg_GOP_Pct,
    ROUND(AVG(Google_Rating), 2)             AS Avg_Google_Rating,
    ROUND(AVG(Reviews_Count), 0)             AS Avg_Reviews
FROM fact_revenue
GROUP BY Segment
ORDER BY Avg_RevPAR DESC;


-- ==============================================================
-- QUERY 13 — Stored Procedure: KPIs for Any Chain
-- Usage: CALL GetChainKPIs('CHN01');
-- ==============================================================
DELIMITER $$
CREATE PROCEDURE GetChainKPIs(IN p_chain_id VARCHAR(10))
BEGIN
    SELECT
        f.Year, f.Quarter,
        c.Chain_Name,
        COUNT(*)                              AS Transactions,
        ROUND(SUM(f.Revenue_USD)/1e6, 2)     AS Revenue_M,
        ROUND(AVG(f.RevPAR_USD), 2)          AS Avg_RevPAR,
        ROUND(AVG(f.ADR_USD), 2)             AS Avg_ADR,
        ROUND(AVG(f.Occupancy_Pct), 2)       AS Avg_Occupancy_Pct,
        ROUND(AVG(f.GOP_Pct), 2)             AS Avg_GOP_Pct,
        COUNT(DISTINCT f.City)               AS Cities_Covered,
        COUNT(DISTINCT f.Country)            AS Countries_Covered
    FROM fact_revenue f
    JOIN dim_chain c ON f.Chain_ID = c.Chain_ID
    WHERE f.Chain_ID = p_chain_id
    GROUP BY f.Year, f.Quarter, c.Chain_Name
    ORDER BY f.Year, f.Quarter;
END$$
DELIMITER ;

-- Run examples:
CALL GetChainKPIs('CHN01');   -- Marriott International
CALL GetChainKPIs('CHN02');   -- Hilton Worldwide
CALL GetChainKPIs('CHN04');   -- Accor

